function initiales(nom) {
  return nom
    .split(" ")
    .map((p) => p[0])
    .join("")
    .toUpperCase();
}

function MembreCard({ m, onClick }) {
  const tone = m.cotisationStatut === "À jour" ? "mint" : "clay";
  return (
    <button
      onClick={onClick}
      className="w-full flex items-center gap-4 px-5 py-4 text-left transition-colors"
    >
      <div
        className="w-11 h-11 rounded-full flex items-center justify-center text-sm font-bold flex-shrink-0"
        style={{ background: C.mist, color: C.emerald }}
      >
        {initiales(m.nom)}
      </div>
      <div className="flex-1 min-w-0">
        <div className="text-sm font-semibold" style={{ color: C.ink }}>
          {m.nom}
        </div>
        <div className="text-xs" style={{ color: C.inkSoft }}>
          {m.poste} · {m.kourel}
        </div>
      </div>
      <Pill tone={tone}>{m.cotisationStatut}</Pill>
      <ChevronRight size={16} color={C.inkSoft} className="flex-shrink-0" />
    </button>
  );
}

function InfoRow({ icon: Icon, label, value }) {
  return (
    <div className="flex items-center gap-3">
      <div className="w-8 h-8 rounded-lg flex items-center justify-center flex-shrink-0" style={{ background: C.mist }}>
        <Icon size={14} color={C.emerald} />
      </div>
      <div>
        <div className="text-[11px] uppercase tracking-wide" style={{ color: C.sage }}>
          {label}
        </div>
        <div className="text-sm font-medium" style={{ color: C.ink }}>
          {value}
        </div>
      </div>
    </div>
  );
}

function MembreDetail({ m, onBack }) {
  const tauxPresence = Math.round((m.presences / (m.presences + m.absences)) * 100);
  const cotisationOk = m.cotisationStatut === "À jour";
  const kamilTone = m.kamilStatut === "Terminé" ? "mint" : m.kamilStatut === "En cours" ? "amber" : "clay";

  return (
    <div className="space-y-5">
      <button
        onClick={onBack}
        className="inline-flex items-center gap-1.5 text-sm font-semibold"
        style={{ color: C.emerald }}
      >
        <ArrowLeft size={16} /> Retour à la liste
      </button>

      <Card>
        <div className="flex items-start justify-between flex-wrap gap-4">
          <div className="flex items-center gap-4">
            <div
              className="w-16 h-16 rounded-2xl flex items-center justify-center text-lg font-extrabold flex-shrink-0"
              style={{ background: `linear-gradient(135deg, ${C.fern}, ${C.emerald})`, color: "#fff", fontFamily: "Plus Jakarta Sans, sans-serif" }}
            >
              {initiales(m.nom)}
            </div>
            <div>
              <h2 className="text-xl font-bold" style={{ color: C.ink, fontFamily: "Plus Jakarta Sans, sans-serif" }}>
                {m.nom}
              </h2>
              <div className="flex items-center gap-2 mt-1">
                <Pill tone="solid">{m.poste}</Pill>
                <span className="text-xs" style={{ color: C.inkSoft }}>
                  {m.kourel}
                </span>
              </div>
            </div>
          </div>
          <Pill tone={cotisationOk ? "mint" : "clay"}>
            Cotisation {m.cotisationStatut}
          </Pill>
        </div>

        <div className="grid sm:grid-cols-3 gap-4 mt-6 pt-5" style={{ borderTop: `1px solid ${C.line}` }}>
          <InfoRow icon={Phone} label="Téléphone" value={m.telephone} />
          <InfoRow icon={MapPin} label="Adresse" value={m.adresse} />
          <InfoRow icon={GraduationCap} label="Profession" value={m.profession} />
        </div>
      </Card>

      <div className="grid sm:grid-cols-3 gap-4">
        <StatCard label="Présences" value={m.presences} delta={`${tauxPresence}% de taux`} icon={CheckCircle2} />
        <StatCard label="Absences" value={m.absences} delta={`${m.retards} retards`} positive={false} icon={XCircle} />
        <StatCard label="Partie du Coran (Kamil)" value={`Juz' ${m.kamilPartie}`} delta={m.kamilStatut} positive={m.kamilStatut !== "À faire"} icon={BookOpen} />
      </div>

      <div className="grid sm:grid-cols-2 gap-5">
        <Card>
          <div className="text-xs font-semibold uppercase tracking-widest mb-3" style={{ color: C.sage }}>
            Poste au sein de la daara
          </div>
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-xl flex items-center justify-center" style={{ background: C.mist }}>
              <Briefcase size={17} color={C.emerald} />
            </div>
            <div>
              <div className="text-sm font-bold" style={{ color: C.ink }}>
                {m.poste}
              </div>
              <div className="text-xs" style={{ color: C.inkSoft }}>
                {m.kourel}
              </div>
            </div>
          </div>
        </Card>

        <Card>
          <div className="text-xs font-semibold uppercase tracking-widest mb-3" style={{ color: C.sage }}>
            Cotisation mensuelle
          </div>
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div
                className="w-10 h-10 rounded-xl flex items-center justify-center"
                style={{ background: cotisationOk ? C.mist : "#F5E2DE" }}
              >
                <Wallet size={17} color={cotisationOk ? C.emerald : C.clay} />
              </div>
              <div>
                <div className="text-sm font-bold" style={{ color: C.ink }}>
                  {m.cotisationMontant} / mois
                </div>
                <div className="text-xs" style={{ color: C.inkSoft }}>
                  Dernier paiement : {m.cotisationDernier}
                </div>
              </div>
            </div>
            <Pill tone={cotisationOk ? "mint" : "clay"}>{m.cotisationStatut}</Pill>
          </div>
        </Card>
      </div>
    </div>
  );
}

function Membres() {
  const [selected, setSelected] = useState(null);
  const [query, setQuery] = useState("");

  if (selected) {
    return <MembreDetail m={selected} onBack={() => setSelected(null)} />;
  }

  const filtered = membresListe.filter((m) => m.nom.toLowerCase().includes(query.toLowerCase()));

  return (
    <div className="space-y-6">
      <SectionTitle
        eyebrow={`${membresListe.length} membres enregistrés`}
        title="Membres"
        action={
          <div className="flex items-center gap-2 rounded-xl px-3 py-2 w-64" style={{ background: C.white, border: `1px solid ${C.line}` }}>
            <Search size={15} color={C.inkSoft} />
            <input
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              placeholder="Rechercher..."
              className="bg-transparent outline-none text-sm w-full"
              style={{ color: C.ink }}
            />
          </div>
        }
      />
      <Card padded={false}>
        {filtered.map((m, i) => (
          <div key={m.id} style={{ borderTop: i === 0 ? "none" : `1px solid ${C.line}` }}>
            <MembreCard m={m} onClick={() => setSelected(m)} />
          </div>
        ))}
        {filtered.length === 0 && (
          <div className="px-5 py-8 text-center text-sm" style={{ color: C.inkSoft }}>
            Aucun membre trouvé.
          </div>
        )}
      </Card>
    </div>
  );
}

